const raw = $input.item.json.body || $input.item.json;

const company_name = (raw.business_name || raw.company_name || '').trim();
let rawEik = (raw.eik || raw.bulstat || '').toString().trim().replace(/[^0-9]/g, '');
const representative = (raw.representative || raw.mol || raw.manager || raw.owner_name || 'Управител').trim();
const email = (raw.email || raw.work_email || '').trim().toLowerCase();
const phone = (raw.phone || raw.phone_number || '').trim();
const monthly_spend = parseFloat(raw.monthly_spend || raw.expected_monthly_expense || 0) || 5000;
const source = (raw.source || 'https://finansprotect.com').trim();

// Check EIK validity (9 or 13 digits)
const isEikValid = (rawEik.length === 9 || rawEik.length === 13);
const vat_number = rawEik ? `BG${rawEik}` : '';
const is_active = isEikValid && company_name.length > 0;

let entity_type = 'EOOD';
let legal_form_bg = 'Еднолично дружество с ограничена отговорност';
let business_structure_en = 'Single-member Limited Liability Company (EOOD)';

const nameUpper = company_name.toUpperCase();
if (nameUpper.includes('ЕТ ') || nameUpper.includes(' ET') || nameUpper.startsWith('ЕТ')) {
  entity_type = 'ET';
  legal_form_bg = 'Едноличен търговец';
  business_structure_en = 'Sole Proprietorship (ET)';
}

return {
  json: {
    company_name,
    business_name: company_name,
    eik: rawEik,
    vat_number,
    representative,
    email,
    phone,
    monthly_spend,
    source,
    entity_type,
    legal_form_bg,
    business_structure_en,
    is_eik_valid: isEikValid,
    is_active,
    verified_at: new Date().toISOString()
  }
};

const item = $input.item.json;

const isEligible = Boolean(item.is_eik_valid && item.is_active && item.email && item.company_name);
const bonus_amount_eur = 150;
const card_tier = "FREE_CARD_PLUS_150_BONUS";
const card_program = "Wallester Business Visa Corporate";
const approval_code = `APP-WB-${Date.now().toString(36).toUpperCase()}`;

return {
  json: {
    ...item,
    is_eligible: isEligible,
    bonus_amount_eur,
    currency: "EUR",
    card_tier,
    card_program,
    approval_code,
    eligibility_status: isEligible ? "APPROVED" : "NEEDS_MANUAL_REVIEW"
  }
};

const item = $input.item.json;

const randHex = Math.random().toString(36).substring(2, 10) + Math.random().toString(36).substring(2, 10);
const application_id = `wal_app_${randHex}`;
const onboarding_token = `tok_${Date.now()}_${randHex.substring(0, 6)}`;
const onboarding_url = `https://wallester.com/business-registration?app_id=${application_id}&eik=${item.eik}&ref=openbalancer&token=${onboarding_token}`;

return {
  json: {
    ...item,
    application_id,
    onboarding_token,
    onboarding_url,
    wallester_status: item.is_eligible ? "APPROVED_PENDING_CLIENT_CONFIRMATION" : "NEEDS_MANUAL_REVIEW"
  }
};

